package robot

import "fmt"

// See defs.go for other definitions

// Step 1

// The four directions, in clockwise order, so that a right turn is
// +1 mod 4 and a left turn is +3 mod 4.
const (
	N Dir = iota
	E
	S
	W
)

func (d Dir) String() string {
	return "NESW"[d:d+1]
}

func Right() {
	Step1Robot.Dir = (Step1Robot.Dir + 1) % 4
}

func Left() {
	Step1Robot.Dir = (Step1Robot.Dir + 3) % 4
}

func Advance() {
	switch Step1Robot.Dir {
	case N:
		Step1Robot.Y++
	case E:
		Step1Robot.X++
	case S:
		Step1Robot.Y--
	case W:
		Step1Robot.X--
	}
}

// Step 2

// Action is the effect of a command on a robot.
type Action int

const (
	RightAction Action = iota
	LeftAction
	AdvanceAction
)

func StartRobot(command chan Command, action chan Action) {
	for c := range command {
		switch c {
		case 'L':
			action <- LeftAction
		case 'R':
			action <- RightAction
		case 'A':
			action <- AdvanceAction
		}
	}
	close(action)
}

func Room(extent Rect, robot Step2Robot, action chan Action, report chan Step2Robot) {
	for a := range action {
		switch a {
		case RightAction:
			robot.Dir = (robot.Dir + 1) % 4
		case LeftAction:
			robot.Dir = (robot.Dir + 3) % 4
		case AdvanceAction:
			pos := robot.Pos
			switch robot.Dir {
			case N:
				pos.Northing++
			case E:
				pos.Easting++
			case S:
				pos.Northing--
			case W:
				pos.Easting--
			}
			if pos.Easting < extent.Min.Easting || pos.Easting > extent.Max.Easting ||
				pos.Northing < extent.Min.Northing || pos.Northing > extent.Max.Northing {
				break // bump wall; stay put
			}
			robot.Pos = pos
		}
	}
	report <- robot
}

// Step 3

// Action3 is an action from a named robot. The name lets the room
// tell apart actions from different robots on the shared channel.
type Action3 struct {
	Name string
	Kind int
}

const (
	ReportAction3 = iota
	RightAction3
	LeftAction3
	AdvanceAction3
)

func StartRobot3(name, script string, action chan Action3, log chan string) {
	for _, c := range script {
		switch c {
		case 'L':
			action <- Action3{name, LeftAction3}
		case 'R':
			action <- Action3{name, RightAction3}
		case 'A':
			action <- Action3{name, AdvanceAction3}
		default:
			log <- fmt.Sprintf("sim: robot %q: bad command %q", name, c)
			action <- Action3{name, ReportAction3}
			return
		}
	}
	action <- Action3{name, ReportAction3}
}

func Room3(extent Rect, robots []Step3Robot, action chan Action3, rep chan []Step3Robot, log chan string) {
	// Check the robot list for problems.
	byName := make(map[string]int)
	for i, r := range robots {
		if _, ok := byName[r.Name]; ok {
			log <- fmt.Sprintf("sim: multiple robots named %q", r.Name)
		} else {
			byName[r.Name] = i
		}
		if r.Name == "" {
			log <- "sim: robot name required"
		}
	}
	byPos := make(map[Pos]int)
	for _, r := range robots {
		byPos[r.Pos]++
	}
	for pos, n := range byPos {
		if n > 1 {
			log <- fmt.Sprintf("sim: multiple robots at %v", pos)
		}
	}
	for _, r := range robots {
		if r.Pos.Easting < extent.Min.Easting || r.Pos.Easting > extent.Max.Easting ||
			r.Pos.Northing < extent.Min.Northing || r.Pos.Northing > extent.Max.Northing {
			log <- fmt.Sprintf("sim: robot %q at %v outside room", r.Name, r.Pos)
		}
	}

	// Simulate until every robot has reported.
	nReported := 0
	seen := make(map[string]bool)
	for a := range action {
		i, ok := byName[a.Name]
		if !ok {
			if !seen[a.Name] {
				seen[a.Name] = true
				log <- fmt.Sprintf("sim: robot %q not in room", a.Name)
			}
		} else {
			switch a.Kind {
			case RightAction3:
				robots[i].Dir = (robots[i].Dir + 1) % 4
			case LeftAction3:
				robots[i].Dir = (robots[i].Dir + 3) % 4
			case AdvanceAction3:
				pos := robots[i].Pos
				switch robots[i].Dir {
				case N:
					pos.Northing++
				case E:
					pos.Easting++
				case S:
					pos.Northing--
				case W:
					pos.Easting--
				}
				if pos.Easting < extent.Min.Easting || pos.Easting > extent.Max.Easting ||
					pos.Northing < extent.Min.Northing || pos.Northing > extent.Max.Northing {
					log <- fmt.Sprintf("sim: robot %q at %v bumps wall", a.Name, pos)
					break // stay put
				}
				bumped := false
				for j, r := range robots {
					if j != i && r.Pos == pos {
						log <- fmt.Sprintf("sim: robot %q at %v bumps robot %q", a.Name, pos, r.Name)
						bumped = true
						break
					}
				}
				if !bumped {
					robots[i].Pos = pos
				}
			}
		}
		if a.Kind == ReportAction3 {
			nReported++
		}
		if nReported == len(robots) {
			rep <- robots
			return
		}
	}
}

